/** El globo ocular: centro y radio en el lienzo. La pantalla lo sombrea como
 *  una esfera (gradiente radial con la luz arriba a la izquierda y un brillo)
 *  y el 3D lo pinta como esfera, no como disco extruido. */
export const GLOBO_OCULAR = { centro: [112, 345] as [number, number], radio: 36 };

export interface BaseExterior {
  /** Trazado SVG cerrado. */
  d: string;
  /** Color natural de relleno. */
  fill: string;
  stroke?: string;
  /** Qué pieza es, para las que la pantalla trata aparte: el globo del ojo (sombreado como esfera) y su nervio óptico. */
  papel?: 'globo' | 'nervio' | 'cornea' | 'iris' | 'pupila' | 'cristalino';
}

